<template><div v-if="open" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/40 p-3"><div class="w-full max-w-2xl max-h-[88vh] overflow-hidden border border-slate-200 bg-white shadow-lg"><div class="flex items-center justify-between border-b border-slate-200 px-4 py-2.5"><div><p class="text-[10px] font-semibold uppercase tracking-wide text-primary">Offplan financing</p><h2 class="text-sm font-semibold text-slate-900">Edit bank financing</h2></div><button @click="close" class="h-7 w-7 border border-slate-300 text-sm">×</button></div><div v-if="loadingData" class="p-8 text-center text-xs text-slate-500">Loading…</div><form v-else @submit.prevent="submit"><div class="grid max-h-[calc(88vh-112px)] gap-2 overflow-y-auto p-3 md:grid-cols-2"><Field v-for="f in textFields" :key="f" :label="label(f)"><input v-model="form[f]" class="input"/></Field><Field label="Loan term months"><input v-model.number="form.loan_term_months" type="number" min="1" class="input"/></Field><Field label="Loan status"><select v-model="form.loan_status" class="input"><option v-for="s in loanStatuses" :key="s" :value="s">{{s}}</option></select></Field><Field label="Approved at"><input v-model="form.approved_at" type="datetime-local" class="input"/></Field><Field label="First payment date"><input v-model="form.first_payment_date" type="date" class="input"/></Field><Field label="Application"><select v-model="form.application" class="input"><option value="0">Select application</option><option v-for="a in applications" :key="a.id" :value="a.id">{{applicationLabel(a)}}</option></select></Field></div><div v-if="error" class="mx-3 mb-2 flex h-7 items-center overflow-hidden border border-red-200 bg-red-50 px-2 text-[10px] text-red-700" :title="error">{{error}}</div><div class="flex justify-end gap-2 border-t border-slate-200 px-3 py-2"><button type="button" @click="close" class="border border-slate-300 px-3 py-1.5 text-xs">Cancel</button><button :disabled="saving" class="bg-primary px-3 py-1.5 text-xs font-semibold text-white">{{saving?'Saving…':'Save changes'}}</button></div></form></div></div></template>
<script>
import OffplanField from "../offplan property/OffplanField.vue";
const blank={bank_name:"",loan_account_number:"",loan_amount:"",interest_rate:"",loan_term_months:0,monthly_payment:"",loan_status:"pending",approved_at:"",first_payment_date:"",notes:"",application:0};
export default{name:"EditOffplanBankFinancing",components:{Field:OffplanField},props:{open:Boolean,id:[String,Number]},data(){return{form:{...blank},applications:[],loadingData:false,saving:false,error:"",loanStatuses:["pending","approved","rejected","active","completed","cancelled"],textFields:["bank_name","loan_account_number","loan_amount","interest_rate","monthly_payment","notes"]}},watch:{open(v){if(v)this.load()}},methods:{label(v){return v.replace(/_/g," ").replace(/\b\w/g,c=>c.toUpperCase())},personName(v){if(!v)return"—";if(typeof v==="string")return v;return[v.first_name,v.middle_name,v.last_name].filter(Boolean).join(" ")||v.name||v.username||"—"},propertyName(p){if(!p)return"—";return p.name||p.title||p.property_name||p.property_type||"Offplan property"},applicationLabel(a){const p=a?.offplan_property,z=p?.property_zone;return[this.personName(a?.customer),p?.developer||"—",this.propertyName(p),z?.name||"—",this.personName(a?.owner)].join(" • ")},async load(){if(!this.id)return;this.loadingData=true;this.error="";try{const [r,ar]=await Promise.all([this.$apiGetById("/get_offplan_bank_financing",this.id),this.$getOffplanApplications()]);const item=r?.data?.data||r?.data||r?.financing||r;const d=ar?.data?.data||ar?.data||ar?.applications||ar;this.applications=Array.isArray(d)?d:(d?.results||d?.applications||[]);this.form={...blank,...item,application:Number(item?.application?.id??item?.application??0)}}catch(e){this.error=e?.message||"Unable to load financing."}finally{this.loadingData=false}},close(){if(!this.saving)this.$emit("close")},async submit(){this.saving=true;this.error="";try{await this.$apiPatch("/update_offplan_bank_financing",this.id,{...this.form,loan_term_months:Number(this.form.loan_term_months),application:Number(this.form.application)});this.$emit("saved");this.$emit("close")}catch(e){this.error=e?.message||"Unable to update financing."}finally{this.saving=false}}}};
</script>
<style scoped>.input{width:100%;border:1px solid #cbd5e1;padding:.4rem .55rem;font-size:.75rem;line-height:1rem;outline:none;background:#fff}.input:focus{border-color:#5f5ffc}</style>